#include <cstdint>
#include <iostream>
static void tick(Vtb_ca_live_group_directed&d){d.clk_i=0;d.eval();d.clk_i=1;d.eval();d.clk_i=0;d.eval();}
static void reset(Vtb_ca_live_group_directed&d){d.rst_ni=0;d.state_update_i=0;d.test_done_valid_i=0;d.candidate_valid_i=0;d.candidate_pattern_id_i=0;tick(d);tick(d);d.rst_ni=1;}
static bool complete(Vtb_ca_live_group_directed&d,unsigned sa,unsigned pat){d.candidate_valid_i=1;d.candidate_pattern_id_i=pat;d.state_update_i=1;d.state_sa_i=sa;d.test_done_valid_i=1;d.test_done_sa_i=sa;tick(d);d.state_update_i=0;d.test_done_valid_i=0;for(unsigned i=0;i<3;++i)tick(d);return (d.frozen_o>>sa)&1;}
int main(){Vtb_ca_live_group_directed d;reset(d);for(unsigned sa=0;sa<3;++sa)if(!complete(d,sa,sa+1)){std::cerr<<"EARLIER_FREEZE_FAIL\n";return 1;}const uint64_t earlier=d.store_o&((1ULL<<45)-1);d.candidate_valid_i=1;d.candidate_pattern_id_i=9;d.state_update_i=1;d.state_sa_i=3;d.test_done_valid_i=1;d.test_done_sa_i=3;tick(d);d.state_update_i=0;d.test_done_valid_i=0;tick(d);if((d.frozen_o&8)||((d.store_o&((1ULL<<45)-1))!=earlier)){std::cerr<<"PARTIAL_FREEZE_OR_MUTATION\n";return 1;}d.state_update_i=1;d.state_sa_i=3;tick(d);d.state_update_i=0;if((d.frozen_o&8)||((d.store_o&((1ULL<<45)-1))!=earlier)){std::cerr<<"UPDATE_MUTATED_EARLIER\n";return 1;}for(unsigned i=0;i<3;++i){tick(d);if(i<2&&(d.frozen_o&8)){std::cerr<<"EARLY_FREEZE\n";return 1;}}if(!(d.frozen_o&8)||((d.store_o&((1ULL<<45)-1))!=earlier)){std::cerr<<"FINAL_FREEZE_OR_EARLIER_MUTATION\n";return 1;}const uint64_t expected=(19ULL|(19ULL<<5)|(19ULL<<10))<<45;if((d.store_o>>45)!=(expected>>45)){std::cerr<<"STALE_MIX\n";return 1;}std::cout<<"L1X4_R_GROUP_PERSISTENCE_PASS earlier_sa_replay=0 earlier_sa_record_mutation=0 stale_generation_mix=0 partial_scan_finalization=FORBIDDEN_AND_VERIFIED group_freeze_partial=NOT_TRIGGERED group_freeze_latest_complete=ALLOWED\n";}
